(()=>{
'use strict';
if(window.__PB904R67_STORE_UI__)return;window.__PB904R67_STORE_UI__=true;
const qs=(s,r=document)=>r?.querySelector?.(s)||null,qsa=(s,r=document)=>r?.querySelectorAll?[...r.querySelectorAll(s)]:[];
const clean=s=>String(s||'').replace(/\s+/g,' ').trim();
const mobile=()=>matchMedia('(max-width:820px)').matches;
let raf=0,shopsCache=null,shopsAt=0;
function storeRoot(){return qs('#storePhotographerWorkspace')}
function textBtn(root,re){return qsa('button',root).find(b=>re.test(clean(b.textContent)))||null}
function selectedLabel(row,fallback){const b=qs('button.active,[aria-selected="true"]',row);return clean(b?.textContent)||fallback}
function brandRow(panel,cat){if(!panel)return null;const rows=qsa('.storeBrandRow,.brandFilters,[id*="BrandFilters"],[id*="brandFilters"]',panel).filter(x=>x!==cat);if(rows[0])return rows[0];const branded=qsa('[data-brand],[data-sale-brand],[data-rental-brand]',panel).map(x=>x.parentElement).filter(Boolean);return branded[0]||null}
function ensureSheet(){let o=qs('#pbR67Sheet');if(o)return o;o=document.createElement('div');o.id='pbR67Sheet';o.className='pbR67Sheet';o.innerHTML='<div class="pbR67SheetBackdrop" data-close></div><section class="pbR67SheetCard" role="dialog" aria-modal="true"><header><div><b></b><small></small></div><button type="button" data-close aria-label="بستن">×</button></header><div class="pbR67SheetBody"></div></section>';document.body.appendChild(o);o.addEventListener('click',e=>{if(e.target.closest('[data-close]'))closeSheet()});return o}
function closeSheet(){qs('#pbR67Sheet')?.classList.remove('open');document.documentElement.classList.remove('pbR67SheetOpen')}
function openOptions(title,subtitle,row,onPick){if(!row)return;const o=ensureSheet(),body=qs('.pbR67SheetBody',o),head=qs('.pbR67SheetCard header',o);qs('b',head).textContent=title;qs('small',head).textContent=subtitle||'';body.innerHTML='';const buttons=qsa('button',row).filter(b=>!b.disabled);if(!buttons.length){body.innerHTML='<div class="pbR67SheetEmpty">گزینه‌ای برای انتخاب وجود ندارد.</div>'}else buttons.forEach(src=>{const b=document.createElement('button');b.type='button';b.className='pbR67SheetOption'+(src.classList.contains('active')||src.getAttribute('aria-selected')==='true'?' active':'');b.innerHTML='<span>'+clean(src.textContent)+'</span>'+(b.classList.contains('active')?'<i>✓</i>':'');b.onclick=()=>{src.click();closeSheet();setTimeout(()=>{onPick?.();schedule()},50)};body.appendChild(b)});o.classList.add('open');document.documentElement.classList.add('pbR67SheetOpen')}
function toolbar(panel,type){if(!panel)return;const cat=qs(type==='sale'?'#saleCategoryFilters':'#itemCategoryFilters',panel)||qs(type==='sale'?'#saleCategoryFilters':'#itemCategoryFilters');const brand=brandRow(panel,cat);if(!cat&&!brand)return;let bar=qs(':scope>.pbR67FilterToolbar',panel);if(!bar){bar=document.createElement('div');bar.className='pbR67FilterToolbar';bar.dataset.type=type;const anchor=qs('.pbR63RentalCalendar',panel)||cat||brand||panel.firstElementChild;anchor?.insertAdjacentElement('beforebegin',bar)}
const buttons=[];
if(cat){let b=qs('[data-r67-cat]',bar);if(!b){b=document.createElement('button');b.type='button';b.dataset.r67Cat='1';bar.appendChild(b)}b.innerHTML='<small>دسته‌بندی</small><b>'+selectedLabel(cat,'همه')+'</b>';b.onclick=()=>openOptions('دسته‌بندی',type==='sale'?'فیلتر کالاهای فروش':'فیلتر تجهیزات اجاره',cat,()=>toolbar(panel,type));buttons.push(b)}
if(brand){let b=qs('[data-r67-brand]',bar);if(!b){b=document.createElement('button');b.type='button';b.dataset.r67Brand='1';bar.appendChild(b)}b.innerHTML='<small>برند</small><b>'+selectedLabel(brand,'همه')+'</b>';b.onclick=()=>openOptions('برند',type==='sale'?'فیلتر برند کالاهای فروش':'فیلتر برند تجهیزات اجاره',brand,()=>toolbar(panel,type));buttons.push(b)}
if(type==='rental'){let b=qs('[data-r67-office]',bar);if(!b){b=document.createElement('button');b.type='button';b.dataset.r67Office='1';b.className='primary';b.textContent='ثبت آفیش';bar.appendChild(b)}b.onclick=()=>{const native=textBtn(panel,/سبد\s*آفیش|ثبت\s*آفیش|ارسال\s*آفیش/);if(native&&native!==b)native.click();else qs('.pbR63OfficeBtn',panel)?.click()};buttons.push(b)}
bar.style.setProperty('--pb-r67-cols',String(Math.max(1,buttons.length)));
cat?.classList.add('pbR67NativeFilterRow');brand?.classList.add('pbR67NativeFilterRow')}
async function shops(){if(shopsCache&&Date.now()-shopsAt<30000)return shopsCache;const r=await fetch('/api/customer/equipment-rental/shops',{credentials:'same-origin'});if(!r.ok)throw new Error('shops');const d=await r.json();shopsCache=Array.isArray(d.shops)?d.shops:[];shopsAt=Date.now();return shopsCache}
function currentShopName(){return clean(qs('#photographerStoreHeaderName')?.textContent||qs('#storeIdentityToggle')?.textContent)}
async function openStorePicker(){const o=ensureSheet(),body=qs('.pbR67SheetBody',o),head=qs('.pbR67SheetCard header',o);qs('b',head).textContent='انتخاب فروشگاه';qs('small',head).textContent='فروشگاه موردنظر را انتخاب کنید';body.innerHTML='<div class="pbR67SheetEmpty">در حال دریافت فروشگاه‌ها…</div>';o.classList.add('open');document.documentElement.classList.add('pbR67SheetOpen');try{const list=await shops(),cur=currentShopName();body.innerHTML='';if(!list.length){body.innerHTML='<div class="pbR67SheetEmpty">فروشگاه دیگری در دسترس نیست.</div>';return}list.forEach(s=>{const b=document.createElement('button');b.type='button';b.className='pbR67StoreOption'+(cur&&clean(s.name)===cur?' active':'');b.innerHTML='<span><b>'+clean(s.name||'فروشگاه')+'</b><small>'+clean([s.city,s.province].filter(Boolean).join('، '))+'</small></span><i>'+(b.classList.contains('active')?'✓':'›')+'</i>';b.onclick=async()=>{try{await fetch('/api/customer/equipment-rental/shops/'+encodeURIComponent(s.id)+'/select',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:'{}'});try{sessionStorage.setItem('photobridge:rental:selected-shop',String(s.id))}catch{};closeSheet();const native=qsa('[data-shop-id],button').find(x=>String(x.dataset?.shopId||'')===String(s.id)||clean(x.textContent)===clean(s.name));if(native)native.click();else location.href='/equipment-rental/book?shopId='+encodeURIComponent(s.id)}catch{}};body.appendChild(b)})}catch{body.innerHTML='<div class="pbR67SheetEmpty">دریافت لیست فروشگاه‌ها انجام نشد.</div>'}}
function storePickerFix(){const t=qs('#storeIdentityToggle');if(!t||t.dataset.pbR67Bound==='1')return;t.dataset.pbR67Bound='1';t.addEventListener('click',e=>{if(!mobile()||!t.classList.contains('switchable'))return;e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();openStorePicker()},true)}
function hideHome(){const root=storeRoot();if(!root)return;qsa('.storeHomeActionsV671,.storeHomeCards,.storeLandingActions,.storeWelcomeActions',root).forEach(x=>x.classList.add('pbR67HideHome'));const nav=qs('#storeSectionNavV673',root);if(nav&&!qs('button.active,[aria-selected="true"]',nav)){const rental=qs('[data-store-panel="equipmentPanel"]',nav)||qsa('[data-store-panel]',nav)[0];rental?.click()}}
function financeShopId(){const u=new URL(location.href).searchParams.get('shopId');if(u)return u;const e=qsa('#storePhotographerWorkspace [data-shop-id]').find(x=>x.dataset.shopId);if(e)return e.dataset.shopId;try{return sessionStorage.getItem('photobridge:rental:selected-shop')||''}catch{return''}}
const money=v=>Number(v||0).toLocaleString('fa-IR')+' تومان';const date=v=>{try{return new Date(v).toLocaleDateString('fa-IR-u-ca-persian')}catch{return''}};
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function resolveShopId(){let id=financeShopId();if(id)return id;const name=currentShopName();if(!name)return'';try{const list=await shops(),s=list.find(x=>clean(x.name)===name);return s?.id||''}catch{return''}}
function renderFinance(d,host){const invoices=Array.isArray(d.invoices)?d.invoices:[],entries=Array.isArray(d.entries)?d.entries:[],payments=Array.isArray(d.payments)?d.payments:[];host.innerHTML=`<div class="pbR67FinanceTabs"><button class="active" data-f="invoices">فاکتورها</button><button data-f="ledger">حساب معین</button><button data-f="payments">دریافتی‌ها</button></div><div class="pbR67FinanceSummary"><span><small>جمع فاکتورها</small><b>${money(d.summary?.invoiceTotal)}</b></span><span><small>پرداخت‌ها</small><b>${money(d.summary?.paymentTotal)}</b></span><span><small>مانده</small><b>${money(d.summary?.balance)}</b></span></div><section data-view="invoices" class="pbR67FinanceView">${invoices.length?invoices.map(x=>`<article class="pbR67InvoiceCard"><div class="head"><span><small>فاکتور</small><b>#${esc(x.invoice_number||'—')}</b></span><em>${esc(x.kind==='sale'?'خرید':'اجاره')}</em></div><div class="body"><span><small>تاریخ</small><b>${date(x.issued_at)}</b></span><span><small>شرح</small><b>${esc(x.item_titles||'—')}</b></span><span><small>مبلغ</small><b>${money(x.total_amount)}</b></span><span><small>وضعیت</small><b>${esc(x.payment_status==='paid'?'پرداخت‌شده':x.status||'ثبت‌شده')}</b></span></div></article>`).join(''):'<div class="pbR67Empty">فاکتوری ثبت نشده است.</div>'}</section><section data-view="ledger" class="pbR67FinanceView" hidden>${entries.length?entries.map(x=>`<details class="pbR67LedgerRow"><summary><span><b>${esc(x.description||'گردش حساب')}</b><small>${date(x.entry_date||x.created_at)}</small></span><strong class="${x.direction==='credit'?'credit':'debit'}">${x.direction==='credit'?'+':'−'} ${money(x.amount)}</strong></summary><div><span>نوع: ${esc(x.entry_type||'—')}</span>${x.booking_id?`<span>آفیش: ${esc(String(x.booking_id).slice(0,8))}</span>`:''}<span>تاریخ ثبت: ${date(x.created_at||x.entry_date)}</span></div></details>`).join(''):'<div class="pbR67Empty">گردش حسابی ثبت نشده است.</div>'}</section><section data-view="payments" class="pbR67FinanceView" hidden>${payments.length?payments.map(x=>`<article class="pbR67PaymentRow"><span><b>${esc(x.description||'دریافتی')}</b><small>${date(x.paid_at||x.entry_date||x.created_at)}</small></span><strong>${money(x.amount)}</strong></article>`).join(''):'<div class="pbR67Empty">دریافتی ثبت نشده است.</div>'}</section>`;qsa('.pbR67FinanceTabs button',host).forEach(b=>b.onclick=()=>{qsa('.pbR67FinanceTabs button',host).forEach(x=>x.classList.toggle('active',x===b));qsa('.pbR67FinanceView',host).forEach(v=>v.hidden=v.dataset.view!==b.dataset.f)})}
async function finance(){const panel=qs('#financePanel');if(!panel||panel.hidden||getComputedStyle(panel).display==='none')return;let host=qs('#pbR67CustomerFinance',panel);if(!host){host=document.createElement('div');host.id='pbR67CustomerFinance';host.className='pbR67CustomerFinance';panel.appendChild(host)}if(host.dataset.loading==='1'||host.dataset.loaded==='1')return;host.dataset.loading='1';host.innerHTML='<div class="pbR67Empty">در حال دریافت امور مالی…</div>';try{const id=await resolveShopId();if(!id)throw 0;const r=await fetch('/api/customer/equipment-rental/finance?shopId='+encodeURIComponent(id),{credentials:'same-origin'});if(!r.ok)throw 0;renderFinance(await r.json(),host);host.dataset.loaded='1';panel.classList.add('pbR67FinanceReady')}catch{host.innerHTML='<div class="pbR67Empty">دریافت امور مالی انجام نشد.</div>'}finally{host.dataset.loading='0'}}
function sync(){raf=0;const root=storeRoot();if(root){root.classList.add('pbR67Store');storePickerFix();hideHome();toolbar(qs('#equipmentPanel',root),'rental');toolbar(qs('#salesPanel',root),'sale');finance()}}
function schedule(){if(!raf)raf=requestAnimationFrame(sync)}
const start=()=>{schedule();const root=qs('#root');if(root)new MutationObserver(schedule).observe(root,{childList:true,subtree:true,attributes:true,attributeFilter:['class','hidden','aria-selected']});document.addEventListener('click',e=>{if(e.target.closest?.('#storeSectionNavV673 button,#itemCategoryFilters button,#saleCategoryFilters button,.storeBrandRow button,.brandFilters button'))setTimeout(schedule,30)},true)};
document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start,{once:true}):start();
})();
